const hash=bytes=>crypto.createHash('sha256').update(bytes).digest('hex');
function command(args){return new Promise((resolve,reject)=>{const child=spawn(args[0],args.slice(1),{cwd:root,stdio:'inherit'});child.on('error',reject);child.on('close',code=>code===0?resolve():reject(new Error(args.join(' ')+' failed (exit '+code+'). Fix the reported problem and run this installer again.')));});}
async function checkPort(port){return new Promise((resolve,reject)=>{const server=net.createServer();server.once('error',()=>reject(new Error('Port '+port+' is still in use. Stop the existing app servers with Ctrl+C before running this installer.')));server.listen(port,'0.0.0.0',()=>server.close(resolve));});}
(async()=>{
 if(!fs.existsSync(path.join(root,'package.json'))||JSON.parse(fs.readFileSync(path.join(root,'package.json'),'utf8')).name!=='training2')throw new Error('Run this file from /workspaces/training2.');
 if(!process.env.DATABASE_URL||!process.env.COGNITO_LOCAL_ENDPOINT||new URL(process.env.COGNITO_LOCAL_ENDPOINT).hostname!=='cognito-local')throw new Error('Run this installer inside the training2 VS Code Dev Container, not Windows PowerShell.');
 for(const port of [3000,3001,5173,5174])await checkPort(port);
 for(const [name,content]of Object.entries(files)){
  const file=path.join(root,name);
  if(!fs.existsSync(file)){if(hashes[name])throw new Error('Expected file missing: '+name);continue;}
  const current=fs.readFileSync(file);
  if(hash(current)!==hashes[name]&&current.toString('utf8').replace(/\r\n/g,'\n')!==content)throw new Error('A file changed after this upgrade was prepared: '+name+'. It has not been overwritten.');
 }
 const backup=path.join(root,'.local','store-upgrade-backup-'+new Date().toISOString().replace(/[:.]/g,'-'));
 const added=[];
 for(const [name,content]of Object.entries(files)){
  const target=path.join(root,name);
  if(fs.existsSync(target)){const saved=path.join(backup,name);fs.mkdirSync(path.dirname(saved),{recursive:true});fs.copyFileSync(target,saved);}else added.push(name);
  fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,content,'utf8');
 }
 fs.mkdirSync(backup,{recursive:true});fs.writeFileSync(path.join(backup,'upgrade-manifest.json'),JSON.stringify({added,replaced:Object.keys(files).filter(n=>!added.includes(n))},null,2));
 console.log('Replacement files installed. Backup: '+backup);
 await command(['pnpm','install','--frozen-lockfile']);
 await command(['node','apps/private-api/src/upgrade-store.ts']);
 await command(['pnpm','--filter','@training2/prisma','codegen']);
 await command(['pnpm','typecheck']);
 await command(['pnpm','build']);
 console.log('Upgrade and type checks complete. Shop: http://localhost:5173/ | Staff: http://localhost:5174/');
 if(process.argv.includes('--no-start')){console.log('Start later with: pnpm -r --parallel --filter "./apps/*" run dev');return;}
 console.log('Starting all four apps. Leave this terminal running; use Ctrl+C to stop.');
 await command(['pnpm','-r','--parallel','--filter','./apps/*','run','dev']);
})().catch(error=>{console.error('\n'+error.message);process.exitCode=1;});
